[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ChartPulse — Track All Markets</title>
  <meta name="description" content="A supercharged charting platform and social network for traders and investors to analyze, discuss, and trade global markets. Free to sign up — $0 forever.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg: #0f0f0f;
      --bg2: #161616;
      --bg3: #1e1e1e;
      --bg4: #252525;
      --border: #2a2a2a;
      --text: #e0e0e0;
      --text2: #a0a0a0;
      --text3: #666;
      --blue: #2962ff;
      --blue-light: #4f7dff;
      --green: #26a69a;
      --red: #f7525f;
      --gold: #f0b90b;
      --font: 'Inter', sans-serif;
    }
    body { background: var(--bg); color: var(--text); font-family: var(--font); font-size: 13px; line-height: 1.5; }
    a { color: inherit; text-decoration: none; }

    /* NAV */
    nav { background: #0f0f0f; border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 100; }
    .nav-inner { max-width: 1440px; margin: 0 auto; display: flex; align-items: center; gap: 0; height: 48px; padding: 0 16px; }
    .nav-logo { font-size: 16px; font-weight: 700; color: #fff; margin-right: 32px; display: flex; align-items: center; gap: 8px; }
    .nav-logo span { color: var(--blue); }
    .nav-links { display: flex; gap: 4px; flex: 1; }
    .nav-links a { padding: 6px 12px; border-radius: 4px; color: var(--text2); font-size: 13px; font-weight: 500; transition: color .15s, background .15s; }
    .nav-links a:hover, .nav-links a.active { color: #fff; background: var(--bg3); }
    .nav-right { display: flex; gap: 8px; align-items: center; }
    .btn { padding: 7px 16px; border-radius: 4px; font-size: 13px; font-weight: 600; cursor: pointer; border: none; transition: opacity .15s; }
    .btn-ghost { background: transparent; color: var(--text2); border: 1px solid var(--border); }
    .btn-ghost:hover { color: #fff; border-color: #555; }
    .btn-primary { background: var(--blue); color: #fff; }
    .btn-primary:hover { opacity: .88; }

    /* MARKET TICKER BAR */
    .ticker-bar { background: var(--bg2); border-bottom: 1px solid var(--border); overflow: hidden; padding: 0; }
    .ticker-scroll { display: flex; gap: 0; overflow-x: auto; scrollbar-width: none; }
    .ticker-scroll::-webkit-scrollbar { display: none; }
    .ticker-item { flex-shrink: 0; padding: 8px 20px; border-right: 1px solid var(--border); cursor: pointer; transition: background .15s; white-space: nowrap; }
    .ticker-item:hover { background: var(--bg3); }
    .ticker-name { font-size: 11px; color: var(--text2); }
    .ticker-price { font-size: 13px; font-weight: 600; color: #fff; }
    .ticker-chg { font-size: 11px; }
    .pos { color: var(--green); }
    .neg { color: var(--red); }
    .neu { color: var(--text2); }

    /* HERO */
    .hero { background: linear-gradient(135deg, #0f0f0f 0%, #0d1a3a 50%, #0f0f0f 100%); padding: 80px 16px 96px; text-align: center; position: relative; overflow: hidden; }
    .hero::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse 800px 400px at 50% 50%, rgba(41,98,255,.08), transparent); pointer-events: none; }
    .hero h1 { font-size: clamp(28px, 4vw, 52px); font-weight: 700; line-height: 1.18; max-width: 800px; margin: 0 auto 20px; color: #fff; }
    .hero h1 em { font-style: normal; color: var(--blue-light); }
    .hero p { font-size: 16px; color: var(--text2); max-width: 560px; margin: 0 auto 36px; line-height: 1.7; }
    .hero-ctas { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
    .hero-ctas .btn { padding: 12px 28px; font-size: 14px; border-radius: 6px; }
    .hero-stat { margin-top: 56px; display: flex; gap: 48px; justify-content: center; flex-wrap: wrap; }
    .hero-stat-item { text-align: center; }
    .hero-stat-item .num { font-size: 28px; font-weight: 700; color: #fff; }
    .hero-stat-item .lbl { font-size: 12px; color: var(--text2); margin-top: 2px; }

    /* MARKET SUMMARY SECTION */
    .section { max-width: 1440px; margin: 0 auto; padding: 32px 16px; }
    .section-header { display: flex; align-items: center; gap: 16px; margin-bottom: 16px; }
    .section-title { font-size: 16px; font-weight: 600; color: #fff; }
    .tabs { display: flex; gap: 2px; background: var(--bg2); border: 1px solid var(--border); border-radius: 6px; padding: 2px; }
    .tab { padding: 5px 14px; border-radius: 4px; cursor: pointer; font-size: 12px; font-weight: 500; color: var(--text2); transition: all .15s; }
    .tab.active { background: var(--bg4); color: #fff; }
    .tab:hover:not(.active) { color: var(--text); }
    .tab-content { display: none; }
    .tab-content.active { display: block; }

    /* MARKET TABLES */
    .market-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 1px; background: var(--border); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
    .market-row { background: var(--bg2); display: flex; align-items: center; justify-content: space-between; padding: 10px 16px; transition: background .12s; cursor: pointer; }
    .market-row:hover { background: var(--bg3); }
    .market-row-left { display: flex; flex-direction: column; }
    .market-row-name { font-size: 13px; font-weight: 500; color: #fff; }
    .market-row-ticker { font-size: 11px; color: var(--text3); }
    .market-row-right { text-align: right; }
    .market-row-price { font-size: 13px; font-weight: 600; color: #fff; }
    .chg-badge { display: inline-block; padding: 2px 7px; border-radius: 3px; font-size: 11px; font-weight: 600; }
    .chg-badge.pos { background: rgba(38,166,154,.18); color: #26a69a; }
    .chg-badge.neg { background: rgba(247,82,95,.18); color: #f7525f; }
    .chg-badge.neu { background: rgba(100,100,100,.18); color: #888; }

    /* SPARKLINE */
    .sparkline { width: 64px; height: 28px; }

    /* FULL TABLE */
    .data-table { width: 100%; border-collapse: collapse; }
    .data-table th { text-align: left; padding: 8px 12px; font-size: 11px; font-weight: 600; color: var(--text3); text-transform: uppercase; letter-spacing: .5px; border-bottom: 1px solid var(--border); }
    .data-table td { padding: 9px 12px; border-bottom: 1px solid rgba(255,255,255,.04); font-size: 12px; color: var(--text); }
    .data-table tr:hover td { background: rgba(255,255,255,.025); }
    .data-table tr:last-child td { border-bottom: none; }
    .table-wrap { background: var(--bg2); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }

    /* TRENDING STOCKS */
    .trending-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 8px; }
    .trending-card { background: var(--bg2); border: 1px solid var(--border); border-radius: 8px; padding: 14px 16px; cursor: pointer; transition: border-color .15s; }
    .trending-card:hover { border-color: #444; }
    .trending-card-top { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px; }
    .trending-ticker { font-size: 14px; font-weight: 700; color: #fff; }
    .trending-company { font-size: 11px; color: var(--text2); margin-top: 2px; }
    .trending-price { font-size: 16px; font-weight: 600; color: #fff; margin-top: 4px; }

    /* IDEAS */
    .ideas-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 12px; }
    .idea-card { background: var(--bg2); border: 1px solid var(--border); border-radius: 8px; overflow: hidden; cursor: pointer; transition: border-color .15s; }
    .idea-card:hover { border-color: #444; }
    .idea-chart-placeholder { height: 120px; background: linear-gradient(135deg, #1a1a2e, #0d1a3a); position: relative; overflow: hidden; }
    .idea-chart-placeholder svg { width: 100%; height: 100%; }
    .idea-body { padding: 12px 14px; }
    .idea-title { font-size: 13px; font-weight: 600; color: #fff; margin-bottom: 6px; line-height: 1.4; }
    .idea-meta { display: flex; gap: 8px; align-items: center; font-size: 11px; color: var(--text3); }
    .idea-author { color: var(--blue-light); font-weight: 500; }
    .idea-tags { display: flex; gap: 4px; margin-top: 8px; flex-wrap: wrap; }
    .idea-tag { background: rgba(41,98,255,.15); color: var(--blue-light); padding: 2px 8px; border-radius: 3px; font-size: 10px; font-weight: 600; }
    .idea-tag.bull { background: rgba(38,166,154,.15); color: var(--green); }
    .idea-tag.bear { background: rgba(247,82,95,.15); color: var(--red); }

    /* INDICATORS */
    .indicator-list { display: flex; flex-direction: column; gap: 0; }
    .indicator-item { display: flex; align-items: center; gap: 14px; padding: 12px 16px; border-bottom: 1px solid var(--border); transition: background .12s; cursor: pointer; }
    .indicator-item:hover { background: var(--bg3); }
    .indicator-item:last-child { border-bottom: none; }
    .indicator-icon { width: 36px; height: 36px; background: var(--bg3); border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 16px; flex-shrink: 0; }
    .indicator-name { font-size: 13px; font-weight: 500; color: #fff; }
    .indicator-author { font-size: 11px; color: var(--text2); }
    .indicator-stats { margin-left: auto; text-align: right; font-size: 11px; color: var(--text3); }

    /* TOP STORIES */
    .stories-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 12px; }
    .story-card { background: var(--bg2); border: 1px solid var(--border); border-radius: 8px; padding: 14px 16px; cursor: pointer; transition: border-color .15s; }
    .story-card:hover { border-color: #444; }
    .story-source { font-size: 10px; font-weight: 700; color: var(--blue-light); text-transform: uppercase; letter-spacing: .5px; margin-bottom: 6px; }
    .story-title { font-size: 13px; font-weight: 500; color: #fff; line-height: 1.45; margin-bottom: 8px; }
    .story-time { font-size: 11px; color: var(--text3); }

    /* FOOTER */
    footer { background: #080808; border-top: 1px solid var(--border); padding: 48px 16px 24px; margin-top: 64px; }
    .footer-inner { max-width: 1440px; margin: 0 auto; }
    .footer-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 32px; margin-bottom: 40px; }
    .footer-col h4 { font-size: 12px; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: .8px; margin-bottom: 14px; }
    .footer-col a { display: block; font-size: 12px; color: var(--text3); margin-bottom: 8px; transition: color .12s; }
    .footer-col a:hover { color: var(--text); }
    .footer-bottom { display: flex; justify-content: space-between; align-items: center; padding-top: 24px; border-top: 1px solid var(--border); flex-wrap: wrap; gap: 12px; }
    .footer-logo { font-size: 15px; font-weight: 700; color: #fff; }
    .footer-copy { font-size: 11px; color: var(--text3); }
    .free-badge { background: linear-gradient(90deg, #26a69a, #2962ff); color: #fff; font-size: 10px; font-weight: 700; padding: 2px 8px; border-radius: 3px; margin-left: 8px; vertical-align: middle; }

    @media (max-width: 768px) {
      .hero h1 { font-size: 26px; }
      .hero-stat { gap: 28px; }
      .nav-links { display: none; }
    }
  </style>
</head>
