  // Generic tab switcher
  function initTabs(tabGroupId, contentPrefix) {
    const group = document.getElementById(tabGroupId);
    if (!group) return;
    group.querySelectorAll('.tab').forEach(tab => {
      tab.addEventListener('click', () => {
        group.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        const target = tab.dataset.tab;
        document.querySelectorAll(`[id^="tab-"]`).forEach(c => {
          if (c.id === 'tab-' + target) c.classList.add('active');
          else if (c.closest && (
            group === document.getElementById('market-tabs') && ['tab-us-stocks','tab-crypto','tab-futures','tab-forex','tab-economy','tab-brokers-tab'].includes(c.id) ||
            group === document.getElementById('ideas-tabs') && ['tab-ideas-popular','tab-ideas-editors'].includes(c.id) ||
            group === document.getElementById('indicators-tabs') && ['tab-ind-popular','tab-ind-editors'].includes(c.id)
          )) c.classList.remove('active');
        });
      });
    });
  }

  // Tab switcher with explicit sibling groups
  function setupTabGroup(tabsId, contentIds) {
    const tabsEl = document.getElementById(tabsId);
    if (!tabsEl) return;
    const tabs = tabsEl.querySelectorAll('.tab');
    tabs.forEach((tab, i) => {
      tab.addEventListener('click', () => {
        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        contentIds.forEach(id => document.getElementById(id) && document.getElementById(id).classList.remove('active'));
        const target = 'tab-' + tab.dataset.tab;
        const el = document.getElementById(target);
        if (el) el.classList.add('active');
      });
    });
  }

  setupTabGroup('market-tabs', ['tab-us-stocks','tab-crypto','tab-futures','tab-forex','tab-economy','tab-brokers-tab']);
