    /* RIGHT PANEL */
    .right-panel { width: 280px; background: var(--bg2); border-left: 1px solid var(--border); display: flex; flex-direction: column; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--bg4) transparent; flex-shrink: 0; }
