    .analyst-badge { display: inline-flex; align-items: center; gap: 4px; padding: 3px 10px; border-radius: 4px; font-size: 11px; font-weight: 700; background: rgba(100,100,100,.2); color: #aaa; }

    /* CANDLE CHART DRAWING */
    .candle-container { position: absolute; inset: 0 64px 0 36px; overflow: hidden; }

    @media (max-width: 900px) {
      .watchlist { display: none; }
