    const numCandles = timeframe === '1D' ? 40 : timeframe === '5D' ? 50 : timeframe === '1M' ? 22 : timeframe === '3M' ? 65 : 90;
    const candleW = Math.max(3, Math.floor((w - 20) / numCandles) - 2);
    const spacing = Math.floor((w - 20) / numCandles);

    let price = timeframe === 'All' ? 180 : timeframe === '5Y' ? 150 : 240;
    const candles = [];
    for (let i = 0; i < numCandles; i++) {
      const change = (Math.random() - 0.48) * 4;
      const open = price;
      price += change;
      const close = price;
      const high = Math.max(open, close) + Math.random() * 2;
      const low = Math.min(open, close) - Math.random() * 2;
      candles.push({ open, close, high, low });
    }

    const allPrices = candles.flatMap(c => [c.high, c.low]);
    const minP = Math.min(...allPrices);
    const maxP = Math.max(...allPrices);
    const range = maxP - minP || 1;
    const toY = p => h - 10 - ((p - minP) / range) * (h - 20);

    candles.forEach((c, i) => {
      const x = 10 + i * spacing + spacing / 2;
      const isGreen = c.close >= c.open;
      const color = isGreen ? '#26a69a' : '#f7525f';
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 1;

      // Wick
      ctx.beginPath();
      ctx.moveTo(x, toY(c.high));
      ctx.lineTo(x, toY(c.low));
      ctx.stroke();

      // Body
      const bodyTop = toY(Math.max(c.open, c.close));
      const bodyBot = toY(Math.min(c.open, c.close));
      const bodyH = Math.max(1, bodyBot - bodyTop);
      if (isGreen) {
        ctx.fillRect(x - candleW / 2, bodyTop, candleW, bodyH);
      } else {
        ctx.strokeRect(x - candleW / 2, bodyTop, candleW, bodyH);
        ctx.globalAlpha = 0.7;
