      const vol = 0.3 + Math.random() * 0.7;
      ctx.fillRect(x - candleW / 2, h - volH * vol, candleW, volH * vol);
    });

    // Axis labels
    ctx.fillStyle = 'rgba(160,160,160,0.6)';
    ctx.font = '9px Inter, sans-serif';
    ctx.textAlign = 'center';
    const labels = timeframe === '1D' ? ['9:30','10:00','11:00','12:00','13:00','14:00','15:00','16:00'] :
                   timeframe === '5D' ? ['Mon','Tue','Wed','Thu','Fri'] :
                   ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    labels.forEach((lbl, i) => {
      const x = (w / labels.length) * i + (w / labels.length) / 2;
      ctx.fillText(lbl, x, h - 2);
    });
  }

