<script>
  // Asset class tabs
  document.getElementById('asset-tabs').querySelectorAll('.asset-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.asset-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      document.querySelectorAll('.section-panel').forEach(p => p.classList.remove('active'));
      const panel = document.getElementById('panel-' + tab.dataset.panel);
      if (panel) panel.classList.add('active');
    });
  });

  // Chart type controls
  document.querySelectorAll('[id$="-chart-ctrl"]').forEach(ctrl => {
    ctrl.querySelectorAll('.ct-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        // Toggle within group based on type
        const val = btn.dataset.ctrl;
        const timeframes = ['1D','1M','3M','1Y','5Y','All'];
        const types = ['Area','Candles'];
        if (timeframes.includes(val)) {
          ctrl.querySelectorAll('.ct-btn').forEach(b => { if (timeframes.includes(b.dataset.ctrl)) b.classList.remove('active'); });
        } else {
          ctrl.querySelectorAll('.ct-btn').forEach(b => { if (types.includes(b.dataset.ctrl)) b.classList.remove('active'); });
        }
        btn.classList.add('active');
      });
    });
  });

  // Session tabs (gainers/losers)
  function setupSessionTabs(tabsId, prefix) {
    const el = document.getElementById(tabsId);
    if (!el) return;
    el.querySelectorAll('.session-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        el.querySelectorAll('.session-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        const val = tab.dataset.stab;
